<?php require_once __DIR__.'/../includes/functions.php'; require_login(['admin']); verify_csrf(); $pdo=db(); if(isset($_POST['add'])){$pdo->prepare('INSERT INTO branches (code,name,location,active) VALUES (?,?,?,1)')->execute([trim($_POST['code']),trim($_POST['name']),trim($_POST['location'])]);flash('ok','تمت الإضافة');header('Location: branches.php');exit;} if(isset($_POST['upd'])){$pdo->prepare('UPDATE branches SET code=?,name=?,location=?,active=? WHERE id=?')->execute([trim($_POST['code']),trim($_POST['name']),trim($_POST['location']),(int)$_POST['active'],(int)$_POST['id']]);flash('ok','تم التعديل');header('Location: branches.php');exit;} $rows=$pdo->query('SELECT * FROM branches ORDER BY id DESC')->fetchAll();$title='الفروع';include __DIR__.'/../includes/header.php'; ?><div class='card p-3'><a href='dashboard.php' class='btn btn-sm btn-outline-secondary mb-2'>رجوع</a><form method='post' class='row g-2 mb-2'><input type='hidden' name='<?= e($config['security']['csrf_key']) ?>' value='<?= e(csrf_token()) ?>'><div class='col'><input class='form-control' name='code' placeholder='Code' required></div><div class='col'><input class='form-control' name='name' placeholder='Name' required></div><div class='col'><input class='form-control' name='location' placeholder='Location' required></div><div class='col'><button class='btn btn-dark w-100' name='add' value='1'>إضافة</button></div></form><table class='table table-bordered table-sm'><tr><th>ID</th><th>Code</th><th>Name</th><th>Location</th><th>Active</th><th></th></tr><?php foreach($rows as $r): ?><tr><form method='post'><input type='hidden' name='<?= e($config['security']['csrf_key']) ?>' value='<?= e(csrf_token()) ?>'><input type='hidden' name='id' value='<?= $r['id'] ?>'><td><?= $r['id'] ?></td><td><input name='code' value='<?= e($r['code']) ?>'></td><td><input name='name' value='<?= e($r['name']) ?>'></td><td><input name='location' value='<?= e($r['location']) ?>'></td><td><select name='active'><option value='1' <?= $r['active']?'selected':'' ?>>1</option><option value='0' <?= !$r['active']?'selected':'' ?>>0</option></select></td><td><button class='btn btn-sm btn-primary' name='upd' value='1'>حفظ</button></td></form></tr><?php endforeach; ?></table></div><?php include __DIR__.'/../includes/footer.php';
